"use client";
import { useState } from "react";
import { useRouter } from "next/navigation";
import { Copy, KeyRound, ShieldCheck, RotateCw, Ban, ExternalLink } from "lucide-react";
import { generateEventScanCode, revokeEventScanCode } from "@/app/actions/events";
import s from "@/components/events/operations/operations.module.css";
export function StaffScanCodePanel({eventId,initialScanCode,initialScanCodeSetAt}:{eventId:string;initialScanCode:string|null;initialScanCodeSetAt:string|null}){
  const [code,setCode]=useState(initialScanCode),[when,setWhen]=useState(initialScanCodeSetAt),[busy,setBusy]=useState(false),[message,setMessage]=useState("");
  const router=useRouter();
  async function generate(){if(code&&!confirm("Replace the staff code? Connected devices using the old code will lose access. Offline devices need to reconnect; their pending scans need the new code to sync."))return;setBusy(true);try{const r=await generateEventScanCode(eventId);if(!r.ok||!r.code)throw new Error(r.reason);setCode(r.code);setWhen(new Date().toISOString());setMessage("Staff code is ready.");router.refresh();}catch(e){setMessage(e instanceof Error?e.message:"Could not generate the staff code.");}finally{setBusy(false);}}
  async function revoke(){if(!confirm("Disable staff access? Online staff scanning stops immediately. Previously prepared offline access expires within 24 hours. Sync queued scans before disabling access."))return;setBusy(true);try{const r=await revokeEventScanCode(eventId);if(!r.ok)throw new Error(r.reason);setCode(null);setWhen(null);setMessage("Staff access disabled.");router.refresh();}catch{setMessage("Could not disable staff access. Please try again.");}finally{setBusy(false);}}
  async function copy(value:string){try{await navigator.clipboard.writeText(value);setMessage("Copied to clipboard.");}catch{setMessage("Copy unavailable. Select the displayed code or link instead.");}}
  return <section className={s.panel}><div className={s.panelHead}><div><h2 className="flex items-center gap-2"><KeyRound size={20} className="text-orange-500"/> Your door team</h2><p className="mt-2">Give staff access to this event’s scanner without sharing your vendor login.</p></div><ShieldCheck className="hidden text-sky-700 sm:block" size={30}/></div>{code?<div className={s.split}><div className="rounded-2xl border border-sky-100 bg-sky-50 p-5"><p className="text-xs font-bold uppercase tracking-widest">Staff access code</p><strong className="my-3 block break-all font-mono text-3xl tracking-widest">{code}</strong><button type="button" className={s.secondary} onClick={()=>void copy(code)}><Copy size={15}/> Copy code</button>{when&&<p className="mt-3">Created {new Date(when).toLocaleString("en-TT")}</p>}</div><div><p>Open the staff desk on each phone, enter this code, name the gate and prepare the offline list before doors open.</p><p className="mt-3 break-all font-mono text-xs">/scan/{eventId}</p><div className={s.actions}><a className={s.secondary} href={`/scan/${eventId}`} target="_blank" rel="noreferrer"><ExternalLink size={15}/> Open staff desk</a><button type="button" className={s.secondary} onClick={()=>void copy(`${window.location.origin}/scan/${eventId}`)}><Copy size={15}/> Copy staff link</button></div><div className={s.actions}><button className={s.secondary} disabled={busy} onClick={generate}><RotateCw size={15}/> Replace code</button><button className={s.danger} disabled={busy} onClick={revoke}><Ban size={15}/> Disable access</button></div><p className="mt-3">Share only with your door team. The code allows ticket lookup, check-in and offline guest-list download for this event.</p></div></div>:<button className={s.button} disabled={busy} onClick={generate}><KeyRound size={17}/>{busy?"Preparing…":"Enable staff access"}</button>}{message&&<p className={s.notice} role="status">{message}</p>}</section>;
}
